"""Embedded four-shade pack for the viewer-supplied 160x144 title design.

The canonical WebP contains exactly four flat RGB colours and no compression variants:
light ``(239,239,240)``, green ``(133,196,93)``, teal ``(31,120,142)`` and black
``(3,3,3)``.  They map in that order to Game Boy shades 0..3.  ``PACK`` stores 217
deduplicated 2bpp tiles followed by the complete 20x18 tile map.
"""
import base64
import hashlib
import zlib


SOURCE_SHA256 = 'e00fa82b0b8a09beaec7542171c6fbb8a91a0b2cdb17d95a3d4bc61f9f2b4e37'
PACK_SHA256 = '04c8a84351bd64f461b459d0740bd2595b3cb8c08e2c8e6f202276467facfcf7'
TILE_COUNT = 217
MAP_BYTES = 20 * 18

PACK = zlib.decompress(base64.b64decode(
    ''))

if len(PACK) != TILE_COUNT * 16 + MAP_BYTES:
    raise AssertionError('viewer title pack length changed')
if hashlib.sha256(PACK).hexdigest() != PACK_SHA256:
    raise AssertionError('viewer title pack checksum changed')
